package com.mushafi.app;
import android.app.Activity;
import android.content.*;
import android.content.pm.*;
import android.net.Uri;
import android.os.Build;
import android.provider.Settings;
import androidx.core.content.FileProvider;
import org.json.*;
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;
/** User-initiated sideload updates; package, version, SHA-256 and signing identity verified. */
final class AppUpdateController {
 interface Listener{void state(String json);}
 private final Activity activity;private final Listener listener;private final ExecutorService io=Executors.newSingleThreadExecutor();private final android.content.SharedPreferences prefs;
 private volatile boolean destroyed,cancelled,busy,pendingInstall;private volatile AppUpdateDownloader downloader;private volatile long transferred,bytesPerSecond,lastAutomaticCheck;private volatile HttpURLConnection connection;private volatile AppUpdatePolicy release;private volatile String state="idle",error="";private volatile int progress;private volatile boolean manual;private String[] notesAr={},notesEn={},notesUr={},notesBn={},notesTr={};
 AppUpdateController(Activity activity,Listener listener){this.activity=activity;this.listener=listener;prefs=activity.getSharedPreferences("app-updates",0);cleanupOld();}
 private long installedCode(){try{PackageInfo p=activity.getPackageManager().getPackageInfo(activity.getPackageName(),0);return Build.VERSION.SDK_INT>=28?p.getLongVersionCode():p.versionCode;}catch(Exception e){return 0;}}
 private String installedVersion(){try{return activity.getPackageManager().getPackageInfo(activity.getPackageName(),0).versionName;}catch(Exception e){return "";}}
 synchronized String snapshot(){try{JSONObject s=new JSONObject().put("status",state).put("error",error).put("progress",progress).put("manual",manual).put("downloaded",transferred).put("bytesPerSecond",bytesPerSecond).put("installedCode",installedCode()).put("installedVersion",installedVersion());AppUpdatePolicy r=release;if(r!=null)s.put("versionCode",r.code).put("version",r.version).put("size",r.size).put("minimumAndroid",r.minSdk).put("notesAr",new JSONArray(Arrays.asList(notesAr))).put("notesEn",new JSONArray(Arrays.asList(notesEn))).put("notesUr",new JSONArray(Arrays.asList(notesUr))).put("notesBn",new JSONArray(Arrays.asList(notesBn))).put("notesTr",new JSONArray(Arrays.asList(notesTr)));return s.toString();}catch(Exception e){return "{}";}}
 private void emit(){final String json=snapshot();activity.runOnUiThread(()->{if(!destroyed&&!activity.isDestroyed())listener.state(json);});}
 private void change(String next,String failure){state=next;error=failure;emit();}
 synchronized void check(boolean explicit){if(destroyed)return;if(busy){if(explicit){manual=true;emit();}return;}if(!explicit&&lastAutomaticCheck>0&&android.os.SystemClock.elapsedRealtime()-lastAutomaticCheck<60000){emit();return;}if(!explicit)lastAutomaticCheck=android.os.SystemClock.elapsedRealtime();manual=explicit;busy=true;change("checking","");io.execute(()->{try{HttpURLConnection c=open(AppUpdatePolicy.MANIFEST);JSONObject d;try(InputStream in=c.getInputStream()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>65536)throw new IOException("Manifest too large");out.write(b,0,n);}d=new JSONObject(out.toString("UTF-8"));}finally{c.disconnect();connection=null;}
  if(!"com.mushafi.app".equals(d.optString("packageName")))throw new IOException("Wrong application");AppUpdatePolicy next=new AppUpdatePolicy(d.getInt("versionCode"),d.getString("versionName"),d.getInt("minSdk"),d.getString("url"),d.getString("sha256"),d.getLong("size"));if(!d.optBoolean("available"))throw new IOException("Release not available");release=next;notesAr=notes(d.optJSONArray("notesAr"));notesEn=notes(d.optJSONArray("notesEn"));notesUr=notes(d.optJSONArray("notesUr"));notesBn=notes(d.optJSONArray("notesBn"));notesTr=notes(d.optJSONArray("notesTr"));prefs.edit().putLong("lastAttempt",System.currentTimeMillis()).apply();if(!next.newerThan(installedCode(),Build.VERSION.SDK_INT)){change(next.code>installedCode()?"unsupported":"current","");return;}change("available","");
 }catch(Exception e){prefs.edit().putLong("lastAttempt",System.currentTimeMillis()-11*60*60*1000L).apply();change("error","check");}finally{busy=false;}});}
 private String[] notes(JSONArray list){if(list==null)return new String[0];ArrayList<String> out=new ArrayList<>();for(int i=0;i<Math.min(6,list.length());i++){String s=list.optString(i);if(!s.isEmpty()&&s.length()<=300)out.add(s);}return out.toArray(new String[0]);}
 private HttpURLConnection open(String address)throws Exception{URL u=new URL(address);if(!"https".equals(u.getProtocol())||!AppUpdatePolicy.HOST.equals(u.getHost()))throw new IOException("Untrusted server");HttpURLConnection c=(HttpURLConnection)u.openConnection();connection=c;c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","Mushafi/"+installedVersion()+" (Android "+Build.VERSION.SDK_INT+")");c.setRequestProperty("Accept-Encoding","identity");c.setUseCaches(false);if(c.getResponseCode()!=200){c.disconnect();throw new IOException("Update server unavailable");}return c;}
 private File directory(){return new File(activity.getCacheDir(),"updates");}private File apk(){return new File(directory(),"Mushafi-update.apk");}
 synchronized void download(){if(destroyed||busy||release==null||!release.newerThan(installedCode(),Build.VERSION.SDK_INT))return;final AppUpdatePolicy expected=release;manual=true;busy=true;cancelled=false;progress=0;transferred=0;bytesPerSecond=0;change("downloading","");io.execute(()->{AppUpdateDownloader transfer=null;File partial=new File(directory(),"update.part");boolean verificationStarted=false;try{
  if(apk().isFile()&&apk().length()==expected.size){try{verifyArchive(apk(),expected);progress=100;transferred=expected.size;change("ready","");return;}catch(Exception ignored){apk().delete();}}
  final String agent="Mushafi/"+installedVersion()+" (Android "+Build.VERSION.SDK_INT+")";
  transfer=new AppUpdateDownloader(expected,directory(),address->{if(!address.equals(expected.url))throw new IOException("Untrusted release");HttpURLConnection c=(HttpURLConnection)new URL(address).openConnection();c.setRequestProperty("User-Agent",agent);return c;},(received,total,speed)->{transferred=received;bytesPerSecond=speed;progress=(int)Math.min(100,received*100/total);emit();});downloader=transfer;if(cancelled||destroyed)transfer.cancel();partial=transfer.download();if(cancelled||destroyed)throw new InterruptedIOException();verificationStarted=true;change("verifying","");verifyArchive(partial,expected);if(cancelled||destroyed)throw new InterruptedIOException();apk().delete();if(!partial.renameTo(apk()))throw new IOException("Could not save release");transfer.verified();progress=100;transferred=expected.size;bytesPerSecond=0;change("ready","");
 }catch(Exception e){partial.delete();if(verificationStarted&&!cancelled&&transfer!=null)transfer.discard();change(cancelled?"available":"error",cancelled?"":verificationStarted?"verify":"download");}finally{downloader=null;busy=false;}});}
 void cancel(){cancelled=true;AppUpdateDownloader d=downloader;if(d!=null)d.cancel();}
 private void verifyArchive(File file,AppUpdatePolicy expected)throws Exception{expected.verify(file);int flags=Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES;PackageManager manager=activity.getPackageManager();PackageInfo remote=manager.getPackageArchiveInfo(file.getAbsolutePath(),flags),local=manager.getPackageInfo(activity.getPackageName(),flags);if(remote==null||!activity.getPackageName().equals(remote.packageName)||(Build.VERSION.SDK_INT>=28?remote.getLongVersionCode():remote.versionCode)!=expected.code||!expected.version.equals(remote.versionName)||!expected.newerThan(installedCode(),Build.VERSION.SDK_INT))throw new SecurityException("Release identity mismatch");if(remote.applicationInfo==null||Build.VERSION.SDK_INT>=24&&remote.applicationInfo.minSdkVersion>Build.VERSION.SDK_INT)throw new SecurityException("Unsupported device");android.content.pm.Signature[] r=Build.VERSION.SDK_INT>=28?remote.signingInfo.getApkContentsSigners():remote.signatures,l=Build.VERSION.SDK_INT>=28?local.signingInfo.getApkContentsSigners():local.signatures;if(r==null||l==null||r.length!=l.length||r.length==0)throw new SecurityException("Missing certificate");Set<String> a=new HashSet<>(),b=new HashSet<>();for(android.content.pm.Signature sig:r)a.add(AppUpdatePolicy.hex(java.security.MessageDigest.getInstance("SHA-256").digest(sig.toByteArray())));for(android.content.pm.Signature sig:l)b.add(AppUpdatePolicy.hex(java.security.MessageDigest.getInstance("SHA-256").digest(sig.toByteArray())));if(!a.equals(b))throw new SecurityException("Signing identity mismatch");}
 synchronized void install(){if(destroyed||busy||release==null||!("ready".equals(state)||"permission".equals(state)))return;busy=true;final AppUpdatePolicy expected=release;io.execute(()->{try{verifyArchive(apk(),expected);activity.runOnUiThread(()->{if(destroyed)return;try{if(Build.VERSION.SDK_INT>=26&&!activity.getPackageManager().canRequestPackageInstalls()){pendingInstall=true;change("permission","");activity.startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+activity.getPackageName())));return;}Uri uri=FileProvider.getUriForFile(activity,activity.getPackageName()+".updates",apk());Intent intent=new Intent(Intent.ACTION_INSTALL_PACKAGE).setDataAndType(uri,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);intent.setClipData(ClipData.newRawUri("Mushafi update",uri));pendingInstall=false;change("ready","");activity.startActivity(intent);}catch(Exception e){change("error","install");}});}catch(Exception e){apk().delete();change("error","verify");}finally{busy=false;}});}
 void resume(){if(pendingInstall){pendingInstall=false;if(Build.VERSION.SDK_INT<26||activity.getPackageManager().canRequestPackageInstalls())install();}emit();}
 private void cleanupOld(){File dir=directory();File[] files=dir.listFiles();if(files!=null)for(File file:files)if(file.getName().endsWith(".part")||System.currentTimeMillis()-file.lastModified()>7L*24*60*60*1000)AppUpdateDownloader.delete(file);}
 void destroy(){destroyed=true;cancel();HttpURLConnection c=connection;if(c!=null)c.disconnect();io.shutdownNow();}
}
